<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Install AfiuCMS</title><link rel="stylesheet" href="/assets/admin.css"></head><body><div class="install-wrap"><div class="brand">Afiu<span>CMS</span></div><h1>First-run installation</h1><p class="muted">Connect a MySQL database and create the first administrator account. AfiuCMS will write the local environment file and run its migrations.</p><?php if (!empty($error)): ?><div class="flash error"><?= e($error) ?></div><?php endif; ?><form method="post" action="/install"><?= csrf_field() ?><div class="card"><h2>Site</h2><div class="field"><label>Site name</label><input name="site_name" value="<?= e($values['site_name'] ?? 'AfiuCMS Site') ?>" required></div></div><br><div class="card"><h2>Database</h2><div class="install-grid"><div class="field"><label>Host</label><input name="db_host" value="<?= e($values['db_host'] ?? '127.0.0.1') ?>" required></div><div class="field"><label>Port</label><input name="db_port" type="number" value="<?= e($values['db_port'] ?? '3306') ?>" required></div><div class="field"><label>Database name</label><input name="db_database" value="<?= e($values['db_database'] ?? 'afiu_cms') ?>" required></div><div class="field"><label>Username</label><input name="db_username" value="<?= e($values['db_username'] ?? 'root') ?>" required></div></div><div class="field"><label>Password</label><input name="db_password" type="password" autocomplete="new-password"></div></div><br><div class="card"><h2>Administrator</h2><div class="install-grid"><div class="field"><label>Name</label><input name="admin_name" value="<?= e($values['admin_name'] ?? '') ?>" required></div><div class="field"><label>Email</label><input name="admin_email" type="email" value="<?= e($values['admin_email'] ?? '') ?>" required></div></div><div class="field"><label>Password</label><input name="admin_password" type="password" minlength="10" autocomplete="new-password" required><div class="muted">Minimum 10 characters.</div></div></div><br><button class="btn primary" type="submit">Install AfiuCMS</button></form></div></body></html>
